import { TestingModule } from '@nestjs/testing';
import { MikroORM } from '@mikro-orm/core';
import { createIntegrationTestModule, cleanDatabase } from './setup';
import { IdempotencyKey } from '../../src/entities/idempotency-key.entity';
import { buildIdempotencyKey } from '../factories/idempotency-key.factory';

describe('IdempotencyKey Repository', () => {
  let module: TestingModule;
  let orm: MikroORM;

  beforeAll(async () => {
    module = await createIntegrationTestModule();
    orm = module.get(MikroORM);
  });

  afterEach(async () => {
    await cleanDatabase(orm);
  });

  afterAll(async () => {
    await module.close();
  });

  it('creates and persists an entity', async () => {
    const em = orm.em.fork();
    const data = buildIdempotencyKey();
    const entity = em.create(IdempotencyKey, data);
    await em.persistAndFlush(entity);
    expect(entity.id).toBeDefined();
  });

  it('retrieves an entity by id', async () => {
    const em = orm.em.fork();
    const data = buildIdempotencyKey();
    const saved = em.create(IdempotencyKey, data);
    await em.persistAndFlush(saved);
    const found = await em.findOne(IdempotencyKey, { id: saved.id });
    expect(found).not.toBeNull();
    expect(found!.id).toBe(saved.id);
  });

  it('returns null for non-existent id', async () => {
    const em = orm.em.fork();
    const found = await em.findOne(IdempotencyKey, {
      id: '00000000-0000-0000-0000-000000000099',
    });
    expect(found).toBeNull();
  });

  it('updates an entity field', async () => {
    const em = orm.em.fork();
    const data = buildIdempotencyKey();
    const saved = em.create(IdempotencyKey, data);
    await em.persistAndFlush(saved);
    saved.key = `updated-${Date.now()}`;
    await em.flush();
    const reloaded = await em.findOne(IdempotencyKey, { id: saved.id });
    expect(reloaded).not.toBeNull();
    expect(reloaded!.key).toEqual(saved.key);
  });

  it('deletes an entity', async () => {
    const em = orm.em.fork();
    const data = buildIdempotencyKey();
    const saved = em.create(IdempotencyKey, data);
    await em.persistAndFlush(saved);
    await em.removeAndFlush(saved);
    const found = await em.findOne(IdempotencyKey, { id: saved.id });
    expect(found).toBeNull();
  });

  it('lists all entities', async () => {
    const em = orm.em.fork();
    const data = buildIdempotencyKey();
    await em.persistAndFlush(em.create(IdempotencyKey, data));
    const all = await em.find(IdempotencyKey, {});
    expect(all.length).toBeGreaterThanOrEqual(1);
  });

  it('finds entity by unique field key', async () => {
    const em = orm.em.fork();
    const data = buildIdempotencyKey({ key: `test-${Date.now()}` });
    const saved = em.create(IdempotencyKey, data);
    await em.persistAndFlush(saved);
    const found = await em.findOne(IdempotencyKey, {
      key: `test-${Date.now()}`,
    });
    expect(found).not.toBeNull();
    expect(found!.id).toBe(saved.id);
  });
});
